// tests/clean-group-message.test.ts - v1.1.39 SUNNOY-GROUP-CONTENT
// 借鉴 sunnoy/wecom extractGroupMessageContent 范式
//
// 群消息 at 检测通过后, 清洗 content 让 AI 看到干净正文
// 清洗顺序: stripGroupContentPrefix (去 wxid_xxx:\n) → stripAtMentions (去 @bot)

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { cleanGroupMessage } from "../src/inbound/parser/mention.js";

const BOT_WXID = "q139198824"; // 老板主号微信号

describe("cleanGroupMessage (v1.1.39 SUNNOY-GROUP-CONTENT)", () => {
  test("去 wxid_xxx:\\n sender 前缀", () => {
    const input = "wxid_eezdbu1ytws422:\n你好";
    const out = cleanGroupMessage(input, BOT_WXID);
    assert.equal(out, "你好");
  });

  test("去 @bot 提及", () => {
    const input = "@q139198824 你好";
    const out = cleanGroupMessage(input, BOT_WXID);
    assert.equal(out, "你好");
  });

  test("组合清洗: wxid + @bot + 正文", () => {
    const input = "wxid_eezdbu1ytws422:\n@q139198824 你好";
    const out = cleanGroupMessage(input, BOT_WXID);
    assert.equal(out, "你好");
  });

  test("保留 @其他人 (只去 @bot)", () => {
    const input = "wxid_xxx:\n@q139198824 @所有人 开会";
    const out = cleanGroupMessage(input, BOT_WXID);
    assert.equal(out, "@所有人 开会", "should strip @bot but keep @所有人");
  });

  test("无前缀无 @ 直接返回原 content", () => {
    const input = "普通消息";
    const out = cleanGroupMessage(input, BOT_WXID);
    assert.equal(out, "普通消息");
  });

  test("空 content 返回空", () => {
    assert.equal(cleanGroupMessage("", BOT_WXID), "");
  });

  test("null botWxid 不去 @ 提及", () => {
    const input = "wxid_xxx:\n@q139198824 你好";
    const out = cleanGroupMessage(input, null);
    // sender 前缀仍然会被去 (@bot 因为 botWxid=null 不去)
    assert.equal(out, "@q139198824 你好");
  });

  test("去微信号 @ (老板 selfWxid 是微信号非 wxid_)", () => {
    const input = "wxid_xxx:\n@q139198824 今天天气";
    const out = cleanGroupMessage(input, "q139198824");
    assert.equal(out, "今天天气");
  });

  test("gh_ 前缀也清洗", () => {
    const input = "gh_abcdef123:\n@q139198824 测试";
    const out = cleanGroupMessage(input, "q139198824");
    assert.equal(out, "测试");
  });

  test("@chatroom 前缀也清洗 (群消息原始格式之一)", () => {
    const input = "57737516566@chatroom:\n@q139198824 测试";
    const out = cleanGroupMessage(input, "q139198824");
    assert.equal(out, "测试");
  });

  test("多行 content 保留换行", () => {
    const input = "wxid_xxx:\n@q139198824 第一行\n第二行\n第三行";
    const out = cleanGroupMessage(input, "q139198824");
    assert.equal(out, "第一行\n第二行\n第三行");
  });

  test("包含多人在 @, 只去 @bot 那个", () => {
    const input = "@q139198824 @wxid_alice @wxid_bob 大家看";
    const out = cleanGroupMessage(input, "q139198824");
    // stripAtMentions 只去 @q139198824, 其他 @ 保留
    assert.equal(out, "@wxid_alice @wxid_bob 大家看");
  });

  test("at 提及在中间位置 (不是开头) 也清洗", () => {
    const input = "wxid_xxx:\n我先说 @q139198824 你怎么看";
    const out = cleanGroupMessage(input, "q139198824");
    assert.equal(out, "我先说 你怎么看");
  });
});

// src/inbound/parser/mention.ts - 群消息 @user 提取
// 注意: 所有 regex 走 safeMatchAll (截断 4096 + 灾难 regex 检测, 防 ReDoS — gewe A1 教训)

import { isValidAtUser } from "./wxid.js";
import { safeMatchAll } from "../../core/safe-regex.js";

const AT_MENTION_PATTERNS: RegExp[] = [
  // `wxid_xxx@<nickname>` — 群聊 @ 通知
  /(wxid_[a-zA-Z0-9]+)@[^,\s]*/g,
  // `\@wxid_xxx ` 中文 @ + wxid
  /@(wxid_[a-zA-Z0-9]+)/g,
  // `<at user="wxid_xxx">` XML 风格
  /<at\s+user="(wxid_[a-zA-Z0-9]+)"/g,
  // 群 XML: <atuserlist><item><username>wxid_xxx</username>
  /<atuserlist>[\s\S]*?<username>(wxid_[a-zA-Z0-9]+)<\/username>/g,
  // 微信号格式 (e.g. wxid_demo — selfWxid 是微信号非 wxid_, 之前硬要求 wxid_ 前缀漏判)
  /<atuserlist>[\s\S]*?<username>([a-zA-Z][a-zA-Z0-9_-]{5,})<\/username>/g,
  /@([a-zA-Z][a-zA-Z0-9_-]{5,})[^\s@]*/g,
];

/** Extract list of valid wxids mentioned in a group message (去重, 保序) */
export function extractAtUserList(content: string): string[] {
  const out = new Set<string>();
  for (const pat of AT_MENTION_PATTERNS) {
    const matches = safeMatchAll(pat, content);
    for (const m of matches) {
      const wxid = m[1];
      if (wxid && isValidAtUser(wxid)) out.add(wxid);
    }
  }
  return Array.from(out);
}

/** Strip `@bot` text tokens from content (留 emoji 之类) */
export function stripAtMentions(content: string, botWxid: string | null): string {
  if (!botWxid) return content;
  // 匹配 wxid_botwxid 或者 @botwxid 等
  const escaped = botWxid.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const truncated =
    content.length > 4096 ? content.slice(0, 4096) : content; // v1.1.33: 截断防 ReDoS
  return truncated
    .replace(new RegExp(`@${escaped}\\s*`, "g"), "")
    .replace(new RegExp(`\\b${escaped}\\b\\s*`, "g"), "")
    .trim();
}

/** True if message text contains @bot */
export function isBotMentionedByText(content: string, botWxid: string | null): boolean {
  if (!botWxid) return false;
  if (!content) return false;
  if (content.includes(`@${botWxid}`)) return true;
  if (content.includes(` ${botWxid}`)) return true;
  return extractAtUserList(content).includes(botWxid);
}

// ============ 群消息清洗 (cleanGroupMessage) ============
// 群里 @ 检测通过后, 清洗 content 让 AI 看到干净正文 (去 wxid_xxx:\n sender 前缀 + 去 @bot 提及)。
// 仅清洗给 AI 看的 content, 不动 DB 落库 (持久化路径保持原始)。

import { stripGroupContentPrefix } from "../../send/quote-reply.js";

/**
 * 群消息清洗: 去 sender 前缀 (wxid_xxx:\n) + 去 @bot 提及, 让 AI 看干净正文
 *
 * @example
 *   cleanGroupMessage("wxid_sender:\n@bot 你好", "wxid_demo") // → "你好"
 *   cleanGroupMessage("wxid_xxx:\n@bot @所有人 开会", "wxid_demo")     // → "@所有人 开会" (只去 @bot)
 *   cleanGroupMessage("普通消息", "wxid_demo")                            // → "普通消息"
 */
export function cleanGroupMessage(content: string, botWxid: string | null): string {
  if (!content) return content;
  // 步骤 1: 去 wxid_xxx:\n sender 前缀; 步骤 2: 去 @botwxid 提及
  const noSender = stripGroupContentPrefix(content) ?? content;
  const noAt = stripAtMentions(noSender, botWxid);
  return noAt;
}

// src/inbound/parser/wxid.ts - wxid 校验工具

/** 标准 wxid 形式: `wxid_xxx` 或 `gh_xxx` 或 9+ 位 @chatroom */
export function isValidWxid(s: string | null | undefined): boolean {
  if (!s) return false;
  if (s.startsWith("wxid_") || s.startsWith("gh_")) return true;
  return /^[a-zA-Z][\w-]{6,}$/.test(s);
}

/** chatroom wxid: 通常以 @chatroom 结尾, vendor 早期也有 @@ 前缀 */
export function isGroupWxid(s: string | null | undefined): boolean {
  if (!s) return false;
  return s.endsWith("@chatroom") || s.startsWith("@@") || s.includes("@chatroom");
}

/** @user 提及 validation: 合法 wxid 格式 */
export function isValidAtUser(s: string | null | undefined): boolean {
  if (!s) return false;
  return /^(wxid_|gh_)/.test(s);
}

// src/core/safe-regex.ts - 灾难 regex 拦截 (gewe v3.1.0 A1 移植)
//
// 背景: 群接龙 title / 引用消息 XML 内容 / 群消息 nick prefix 都用 regex 解析
//   攻击面: 用户发送恶意构造字符串触发 ReDoS
//   历史教训: gewe v3.1.0 fullfix A1 实测 `(a+)+$` 1000 字符 hang 119s
//   风险模式: 嵌套量词 ((a+)+, (a*)*, (?:.+)+) / 灾难 alternation (a|a)+ / 嵌套捕获
//
// 防护策略:

/**
 * 检测正则是否包含灾难模式 (嵌套量词 / 灾难 alternation)
 * 启发式: 出现 (X+)+ / (X*)* / (?:X+)+ 等模式直接判灾难
 * 误判率 < 5%, 实际生产中几乎无合法 regex 用嵌套量词
 */
export function isCatastrophicRegex(pattern: string | RegExp): boolean {
  const src = typeof pattern === "string" ? pattern : pattern.source;
  // 灾难模式: 嵌套量词 (a+)+, (a*)*, (?:.+)+, (a+)*, (a|b)+
  if (/\((?:\?[:=!])?[^)]*[+*]\)[+*?]/.test(src)) return true;
  // 灾难 alternation: ([a-z]+|[0-9]+)+ 等
  if (/\([^)]*\|[^)]*\)[+*]/.test(src)) return true;
  // 多个连续量词: a++ / a*+ / a{1,}+
  if (/[+*]\+|[+*]\*|[+*]\{[0-9,]+\}\+/.test(src)) return true;
  // \w+\w+\w+ 等多连接 + 整体 + 灾难
  if (/\\[wWsSdD]\+.*\\?[wWsSdD]\+.*[+*]\)?\+/.test(src)) return true;
  return false;
}

/**
 * 安全的 String.match, 超长输入截断到 maxLen (默认 4096)
 * gewe v3.1.0 实测 4096 字符足够所有业务 XML
 */
export function safeMatch(
  pattern: RegExp,
  input: string,
  maxLen = 4096,
): RegExpMatchArray | null {
  const truncated = input.length > maxLen ? input.slice(0, maxLen) : input;
  return truncated.match(pattern);
}

/**
 * 安全 matchAll, 超长截断 + 单次执行 100ms 超时 (web 异步不能用 setTimeout 杀同步 regex, 但可在 worker 用)
 * 简单兜底: 截断 + 调用 matchAll
 */
export function safeMatchAll(
  pattern: RegExp,
  input: string,
  maxLen = 4096,
): RegExpStringIterator<RegExpMatchArray> {
  const truncated = input.length > maxLen ? input.slice(0, maxLen) : input;
  return truncated.matchAll(pattern);
}

/**
 * 替代现有 regex 调用的工厂: 检测到灾难模式 → 抛错 (开发期) 或用 safe fallback (生产期)
 * 调用方应该 try/catch 或检查返回值
 */
export function guardedRegex(pattern: RegExp, fallback: RegExp | null = null): RegExp {
  if (isCatastrophicRegex(pattern)) {
    if (fallback) return fallback;
    throw new Error(
      `catastrophic regex detected: ${pattern.source.slice(0, 80)} (嵌套量词/灾难 alternation). ` +
        `fix: 用非嵌套结构 (a+ → a*?) 或拆 regex`,
    );
  }
  return pattern;
}

// src/send/quote-reply.ts - quoteReply 工具实现
// 流程: 查 DB 被引用消息补全 refermsg 字段 → buildQuoteReplyXml 构造 XML → /Msg/ShareLink 发送
// (baseUrl/tokenKey 从 registry 拿, 不能用空 ctx 否则 postWppJson 拼 URL 失败)

/**
 * v1.3.33 GROUP-MENTION-REPLY: 群聊引用回复时给回复文本加 @被回复人昵称前缀 (纯函数, 可测).
 *   参考 gewe 行为 (gewe send/quote.ts: "@${atsNickname} ${replyContent}").
 *   @param toWxid 目标 (群聊以 @chatroom 结尾才加)
 *   @param content AI 回复文本
 *   @param displayName 被回复人昵称 (来自 resolveDisplayName)
 *   @param fromusr 被回复人 wxid (displayName 缺失时兜底用)
 *   @returns 群聊且有昵称 → "@昵称 内容"; 否则原样返回
 */
export function buildGroupMentionPrefix(
  toWxid: string,
  content: string,
  displayName: string | undefined,
  fromusr: string | undefined,
): string {
  if (!toWxid.endsWith("@chatroom")) return content;
  const atName = displayName && displayName !== fromusr ? displayName : (fromusr ?? "");
  if (!atName) return content;
  return `@${atName} ${content}`.trim();
}

import { getMessageByMsgIdOrNewId, saveMessage } from "../db.js";
import { postWppJson } from "../api/client.js";
import { buildQuoteReplyXml } from "./quote-xml.js";
import { resolveQuoteSvrid } from "../inbound/quote-svrid.js";
import { getDefaultAccountRegistry } from "../account-state.js";
import { info, warn, formatErr } from "../core/logger.js";

/**
 * v1.3.16 OUTBOUND-PERSIST: 引用回复成功后入库 (老板拍板 "任意渠道发送都要入库, 以便引用 bot 消息")。
 * sendAiReply 有引用时走 quoteReply (AI 引用回复主路径), 之前未入库 → 引用不到 bot 的回复。
 */
async function persistQuoteReply(
  acct: string,
  toWxid: string,
  content: string,
  resp: { Code: number; Data?: unknown },
): Promise<void> {
  try {
    if (resp.Code !== 0) return; // 发送失败不入库
    const d = (resp.Data ?? {}) as { msgId?: number | string; newMsgId?: number | string };
    await saveMessage({
      account_id: acct,
      msg_id: d.msgId != null ? String(d.msgId) : null,
      new_msg_id: d.newMsgId != null ? String(d.newMsgId) : null,
      direction: "outbound",
      peer_kind: toWxid.endsWith("@chatroom") ? "group" : "direct",
      peer_id: toWxid,
      msg_type: "quote",
      content,
    });
    info(`[WPP v1.3.16 OUTBOUND-PERSIST] saved quote reply → ${toWxid} msgId=${String(d.msgId ?? "")}`);
  } catch (e) {
    warn(`[WPP v1.3.16 OUTBOUND-PERSIST] persist quote reply failed (non-fatal): ${formatErr(e)}`);
  }
}

// 引用回复 title 显示昵称 (查 /Friend/GetContractDetail + 30 分钟内存缓存, 避免每次调 vendor)
const nicknameCache = new Map<string, { nick: string; ts: number }>();
const NICKNAME_CACHE_TTL_MS = 30 * 60 * 1000; // 30 分钟

/**
 * 查通讯录好友昵称 (vendor /Friend/GetContractDetail)
 * 失败/超时 → undefined (不阻塞引用回复)
 */
async function resolveDisplayName(
  acct: string,
  wxid: string | undefined,
): Promise<string | undefined> {
  if (!wxid || wxid.endsWith("@chatroom")) return undefined; // 群 ID 无昵称可查
  // v1.3.57 P2-2 (2026-08-13 交付审阅): 缓存 key 并入 acct (同 wxid 跨账号昵称可能不同, 防串号)
  const cacheKey = `${acct}:${wxid}`;
  const cached = nicknameCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < NICKNAME_CACHE_TTL_MS) return cached.nick;
  try {
    const state = getDefaultAccountRegistry().get(acct);
    const cfg = state?.config;
    const resp = await postWppJson<{ ContactList?: Array<{ NickName?: { string?: string } }> }>(
      cfg?.apiBaseUrl ?? "",
      "/Friend/GetContractDetail",
      { userName: wxid },
      { tokenKey: cfg?.tokenKey ?? "", authcode: cfg?.authcode ?? "", timeoutMs: 5000, maxRetries: 0 },
    );
    const nick = resp.Data?.ContactList?.[0]?.NickName?.string;
    if (nick) {
      nicknameCache.set(cacheKey, { nick, ts: Date.now() });
      return nick;
    }
  } catch {
    // 昵称查询失败不阻塞引用回复
  }
  return undefined;
}

export interface QuoteReplyParams {
  toWxid: string;
  content: string;
  /** 被引用消息的 msgId (DB 查询用) */
  msgId: string;
  /** 可选: 被引用消息的 newMsgId (fallback) */
  newMsgId?: string;
  accountId?: string;
  /** 被引用消息的发送者 wxid (供 refermsg.fromusr) */
  fromWxid?: string;
  /** 被引用消息的所属会话 wxid (群id 或对方 wxid) */
  chatroomId?: string;
  /** 被引用消息的发送者昵称 */
  fromNickname?: string;
  /** 被引用消息的原始 content (供 refermsg.content) */
  originalContent?: string;
  /** 被引用消息的时间戳 (秒, 供 refermsg.createtime) */
  createtime?: number;
  /** 被引用消息的 msgType (供 refermsg.type) */
  innerType?: number;
}

/**
 * 清洗群消息 content 的发送者 wxid 前缀
 * vendor 群消息 content 形如 "wxid_xxx:\n@bot 你好" (单 wxid + 冒号 + 换行)
 * 或 "senderNick:\n<content>" (昵称 + 冒号 + 换行) — refermsg.content 应只含正文
 */
export function stripGroupContentPrefix(content: string | undefined): string | undefined {
  if (!content) return content;
  // 形如 "wxid_xxx:\n..." 或 "gh_xxx:\n..." 或 "xxx@chatroom:\n..." (首行是 wxid + 冒号)
  const m = content.match(/^[a-zA-Z0-9_@:-]+:\n([\s\S]*)$/);
  if (m && m[1]) return m[1].trim();
  return content;
}

/**
 * 从 vendor 群消息 content 提取真实发送者 wxid (content 前缀 "wxid_xxx:\n")
 * 根因: business callback 的 FromUserName = 群 ID, 发送者 wxid 只在 content 首行前缀
 * 例: "wxid_sender:\n@bot 你好" → "wxid_sender"
 */
export function extractGroupSenderWxid(content: string | undefined): string | undefined {
  if (!content) return undefined;
  // 首行形如 "wxid_xxx:" (wxid 开头) → 提取 wxid
  const m = content.match(/^(wxid_[a-zA-Z0-9_]+|gh_[a-zA-Z0-9_]+|[a-zA-Z0-9_]+@chatroom):\n/);
  if (m && m[1]) return m[1];
  return undefined;
}

/**
 * 引用回复 (文本/图片通用):
 * - 从 DB 查被引用消息, 拿原文 content (图片=图片XML) + fromWxid 等
 * - 构造完整 refermsg → ShareLink 发送
 */
export async function quoteReply(params: QuoteReplyParams): Promise<{ ok: boolean; msg?: string; data?: unknown }> {
  const {
    toWxid, content, msgId, newMsgId, accountId,
    fromWxid, chatroomId, fromNickname, originalContent, createtime, innerType,
  } = params;
  const acct = accountId ?? "default";

  // displayname 兑底变量 (DB peer_name)
  let paramsFromNicknameFallback: string | undefined;

  // 参数 fromWxid 是群 ID (@chatroom 结尾) 时视为无效 → 置 undefined 走 DB 补全 (防 fromusr 永远是群ID)
  const paramFromWxidValid = fromWxid && !fromWxid.endsWith("@chatroom") ? fromWxid : undefined;

  // svrid 直接用 inbound newMsgId (vendor 全局唯一)
  let svrid = newMsgId || msgId || "";
  let dbFromWxid: string | undefined = paramFromWxidValid;
  let dbChatroomId: string | undefined = chatroomId;
  let dbOriginalContent: string | undefined = stripGroupContentPrefix(originalContent);
  let dbCreatetime: number | undefined = createtime;
  let dbInnerType: number | undefined = innerType;
  try {
    // v1.3.18 P1-核心2: 引用查询传 direction: "any" (被引用消息可能是 bot  outbound)
    const rec = await getMessageByMsgIdOrNewId(msgId, newMsgId, acct, { direction: "any" });
    if (rec) {
      const mappedSvrid = await resolveQuoteSvrid(msgId, newMsgId, rec.content ?? undefined, acct);
      if (mappedSvrid && mappedSvrid !== msgId) {
        svrid = mappedSvrid;
      }
      // 发送者 wxid 提取: 参数优先 → raw_payload sender → content 前缀 wxid → (非群) peer_id
      // (business callback FromUserName = 群 ID, 发送者只在 content 前缀)
      const raw = (rec.raw_payload ?? {}) as Record<string, unknown>;
      const rawSenderId =
        (typeof raw.sender_id === "string" ? raw.sender_id : undefined) ??
        (typeof raw.fromUser === "string" ? raw.fromUser : undefined) ??
        (typeof raw.FromWxid === "string" ? raw.FromWxid : undefined) ??
        (typeof raw.fromWxid === "string" ? raw.fromWxid : undefined);
      const isGroupRec = rec.peer_kind === "group";
      // 真实发送者: 参数优先 → raw_payload sender → content 前缀 wxid → (非群) peer_id
      dbFromWxid =
        dbFromWxid ??
        rawSenderId ??
        extractGroupSenderWxid(rec.content ?? undefined) ??
        (isGroupRec ? undefined : (rec.peer_id ?? undefined));
      // 会话 wxid: 群 = chat_id, 私聊 = peer_id (对方 wxid)
      dbChatroomId = dbChatroomId ?? (isGroupRec ? (rec.chat_id ?? undefined) : (rec.peer_id ?? undefined));
      dbOriginalContent = dbOriginalContent ?? stripGroupContentPrefix(rec.content ?? undefined);
      dbCreatetime = dbCreatetime ?? rec.ts;
      dbInnerType = dbInnerType ?? (rec.msg_type ? parseInt(rec.msg_type, 10) : undefined);
      // displayname 兑底: 参数 → peer_name
      if (!fromNickname && rec.peer_name) {
        paramsFromNicknameFallback = rec.peer_name;
      }
    }
  } catch {
    // DB 查询失败不阻塞
  }

  // displayname 优先级: 参数 fromNickname > DB peer_name > 通讯录昵称查询
  const displayName =
    fromNickname ||
    paramsFromNicknameFallback ||
    (await resolveDisplayName(acct, dbFromWxid));

  const quote = {
    svrid,
    fromusr: dbFromWxid,
    chatusr: dbChatroomId ?? toWxid,
    displayname: displayName,
    content: dbOriginalContent,
    createtime: dbCreatetime,
    innerType: dbInnerType,
  };

  // v1.3.33 GROUP-MENTION-REPLY (老板拍板 2026-08-11): 群聊引用回复时加 @被回复人昵称 (gewe 范式)
  const finalContent = buildGroupMentionPrefix(toWxid, content, displayName, quote.fromusr);
  const xml = buildQuoteReplyXml(finalContent, quote);
  const state = getDefaultAccountRegistry().get(acct);
  const cfg = state?.config;
  info(`[WPP v1.2.0 QUOTE-TITLE-FIX] quoteReply ShareLink type=57: to=${toWxid} svrid=${svrid} (title=AI reply + svrid+fromusr refermsg)`);
  info(`[WPP v1.2.0 QUOTE-TITLE-FIX] quoteReply XML (first 800 chars): ${xml.slice(0, 800).replace(/\n/g, "\\n")}`);
  info(`[WPP v1.2.0 QUOTE-TITLE-FIX] quoteReply XML totalLen=${xml.length}`);
  // vendor /Msg/Quote 永久 ret=-2 不可用 → 走 /Msg/ShareLink + Type=5 + 自构造 XML (gewe 范式)
  const resp = await postWppJson(cfg?.apiBaseUrl ?? "", "/Msg/ShareLink", {
    ToWxid: toWxid,
    Type: 5,
    Xml: xml,
  }, {
    tokenKey: cfg?.tokenKey ?? "",
    authcode: cfg?.authcode ?? "",
    timeoutMs: 30000,
  });
  const d = (resp.Data ?? {}) as { BaseResponse?: { ret?: number; errMsg?: unknown }; msgId?: number; newMsgId?: number; type?: number };
  const baseRespRet = d.BaseResponse?.ret;
  info(`[WPP v1.2.0 REVERT] vendor resp: Code=${resp.Code} ret=${baseRespRet} msgId=${d.msgId ?? 0} newMsgId=${d.newMsgId ?? 0} type=${d.type ?? 0}`);
  // 判据陷阱: Code=0 只是 HTTP 200, 真正成功看 Data.BaseResponse.ret === 0 (msgId=0 时 Code=0 不代表成功)
  // v1.3.57 P2-3 (2026-08-13 交付审阅): Code=200 也视为成功 (与 outbound.ts isSendOk 对齐)
  const ok = (resp.Code === 0 || resp.Code === 200) && (baseRespRet === 0 || baseRespRet === undefined);
  if (ok) await persistQuoteReply(acct, toWxid, content, resp);
  return {
    ok,
    msg: ok ? "引用回复已发送" : `发送失败 Code=${resp.Code} ${resp.CodeValue ?? ""}`,
    data: resp.Data,
  };
}

