// 范式仿 本项目/src/storage/db/factory.ts
// 关键: lazy init, backend 切换抛错 (防 multi-process 状态漂移), 暴露 resetAdapter 给 tests

import { info } from "../../core/logger.js";
import type { DbAdapter, ResolvedDbConfig } from "./types.js";
import { createMysqlAdapter } from "./mysql.js";

let current: DbAdapter | null = null;
let resolvedCfg: ResolvedDbConfig | null = null;

/**
 * Set backend impl (called from gateway startup)
 * Throws if already initialized with different backend
 */
export function setBackend(cfg: ResolvedDbConfig): DbAdapter {
  if (current) {
    if (
      resolvedCfg &&
      resolvedCfg.mysql.host === cfg.mysql.host &&
      resolvedCfg.mysql.database === cfg.mysql.database
    ) {
      // 同一 backend 重设, 返回现有 adapter
      return current;
    }
    throw new Error(
      `setBackend: DB already initialized, call resetAdapter() first (current=${resolvedCfg?.mysql.host}/${resolvedCfg?.mysql.database})`,
    );
  }
  resolvedCfg = cfg;
  current = createMysqlAdapter(cfg);
  info(`db factory: backend=${cfg.backend} host=${cfg.mysql.host}/${cfg.mysql.database}`);
  return current;
}

export function getAdapter(): DbAdapter {
  if (!current) {
    throw new Error(
      "db factory: adapter not initialized — call setBackend() at plugin startup",
    );
  }
  return current;
}

export function currentBackendName(): string | null {
  return current?.backendName ?? null;
}

export function currentConfig(): ResolvedDbConfig | null {
  return resolvedCfg;
}

/** 测试用 — 清掉当前 adapter, 允许重新 setBackend */
export function resetAdapter(): void {
  if (current) {
    try {
      current.close().catch(() => {
        /* ignore */
      });
    } catch {
      /* ignore */
    }
  }
  current = null;
  resolvedCfg = null;
}

/**
 * 测试用 — 直接注入 adapter (跳过 createMysqlAdapter + 真实 DB 连接)
 * 命名 _forTest 显式标"测试 only", 生产代码不应调
 */
export function setAdapterForTest(adapter: DbAdapter): void {
  current = adapter;
  // resolvedCfg 留 null — setBackend 不再可用 (会撞 isResolved 校验)
}

/**
 * 从 plugin config.json storage block 反推 ResolvedDbConfig
 * (单账号 demo 用不到, 但为多账号 / 不同 schema 留入口)
 */
export function resolveDbConfig(input: {
  backend: "mysql" | "mariadb" | "sqlite";
  mysql: ResolvedDbConfig["mysql"];
}): ResolvedDbConfig {
  return {
    backend: input.backend === "sqlite" ? "sqlite" : "mysql",
    mysql: input.mysql,
  };
}

// core/logger.ts - 仿 pino 接口日志 (兼容现有 log.info 调用 + 新代码函数式 info/warn/error)
// 范式仿 本项目/src/core/logger.ts
// 关键: formatErr 自动保留 stack (silent killer 永久救回)

import { PLUGIN_VERSION } from "./constants.js";

const LOG_TAG = `[WPP v${PLUGIN_VERSION}]`;

/**
 * formatErr — Error 实例保留 stack; 非 Error 实例走 String()
 * silent killer 永久救回: 之前 18+ 处只打 e.message 漏 stack, prod 难定位
 */
export function formatErr(err: unknown): string {
  if (err instanceof Error) {
    if (err.stack) return `${err.name}: ${err.message}\n${err.stack}`;
    return `${err.name}: ${err.message}`;
  }
  if (err === null || err === undefined) return String(err);
  if (typeof err === "string") return err;
  try {
    return JSON.stringify(err);
  } catch {
    return String(err);
  }
}

type Level = "INFO" | "WARN" | "ERROR" | "DEBUG";
type Fields = Record<string, unknown>;

function fmtValue(v: unknown): string {
  if (typeof v === "string") {
    return /[\s,=]/.test(v) ? JSON.stringify(v) : v;
  }
  if (v === null || v === undefined) return String(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (v instanceof Error) {
    return `"${formatErr(v).replace(/"/g, '\\"').replace(/\n/g, "\\n")}"`;
  }
  try {
    return JSON.stringify(v) ?? "null";
  } catch {
    return String(v);
  }
}

function fmtFields(fields?: Fields): string {
  if (!fields) return "";
  const parts: string[] = [];
  for (const [k, v] of Object.entries(fields)) {
    if (v === undefined) continue;
    parts.push(`${k}=${fmtValue(v)}`);
  }
  return parts.length ? " " + parts.join(" ") : "";
}

function emit(level: Level, msg: string, fields?: Fields): void {
  const line = `${new Date().toISOString()} ${level} ${LOG_TAG} ${msg}${fmtFields(fields)}`;
  if (level === "ERROR") console.error(line);
  else if (level === "WARN") console.warn(line);
  // eslint-disable-next-line no-console -- 中心 logger INFO/DEBUG 必需
  else console.log(line);
}

/**
 * Normalize fields-or-error arg into Fields record.
 * Error instances → { err: "<formatErr>" }, primitives → { value: v }
 */
function normalize(arg: unknown): Fields | undefined {
  if (arg === undefined) return undefined;
  if (arg instanceof Error) return { err: formatErr(arg) };
  if (typeof arg === "object" && arg !== null) return arg as Fields;
  return { value: arg };
}

// ============ 函数式 (本项目 风格 — 新代码推荐) ============

export function info(msg: string, fieldsOrErr?: Fields | unknown): void {
  emit("INFO", msg, normalize(fieldsOrErr));
}

export function warn(msg: string, fieldsOrErr?: Fields | unknown): void {
  emit("WARN", msg, normalize(fieldsOrErr));
}

export function error(msg: string, err?: unknown): void {
  emit("ERROR", msg, normalize(err));
}

export function debug(msg: string, fields?: Fields): void {
  if (process.env.WPP_DEBUG !== "1") return;
  emit("DEBUG", msg, fields);
}

// ============ 对象式 (兼容现有 log.info/warn/error/debug 调用) ============

function objectStyle(level: Level) {
  return (msg: string, fieldsOrErr?: Fields | unknown) => {
    emit(level, msg, normalize(fieldsOrErr));
  };
}

export const logObj = {
  info: objectStyle("INFO"),
  warn: objectStyle("WARN"),
  error: objectStyle("ERROR"),
  debug: objectStyle("DEBUG"),
} as const;

/** 默认 export = logObj 对象 (兼容 `import log from ...; log.info(...)`) */
export default logObj;

