        `SELECT svrid FROM wpp_svrid_mapping WHERE account_id = ? AND msg_md5 = ? ORDER BY captured_at DESC LIMIT 1`,
        [accountId, md5],
      );
      return rows.length > 0 ? String(rows[0]!.svrid) : null;
    },

