// src/accounts/account-registry.ts - 多账号 registry class (显式 start/stop/get/list API)
// 关键设计:

import { logObj as log } from "../core/logger.js";
import { upsertAccount, getAccounts, getAccount } from "../db.js";
import { AccountContext } from "./account-context.js";
import type { AccountRecord } from "../storage/db/types.js";
import type { WppAccountConfig } from "../types.js";

export class AccountRegistry {
  private readonly contexts = new Map<string, AccountContext>();
  /** inFlight Map 序列化并发 start (防多个 caller 同时 start 同 accountId → 后建覆盖先建导致泄漏) */
  private readonly inFlight = new Map<string, Promise<AccountContext>>();

  // ============ CRUD ============

  /**
   * 注册一个新账号. 已存在同 ID 返回 existing (幂等).
   * 并发安全: 同 accountId 并发调用只创建 1 个 context, 其余等待并收到相同 promise.
   * 抛错条件: enabled=false / tokenKey 空.
   */
  async start(accountId: string, cfg: WppAccountConfig): Promise<AccountContext> {
    const inflight = this.inFlight.get(accountId);
    if (inflight) {
      log.debug(`registry.start: inFlight hit for ${accountId}, awaiting`);
      return inflight;
    }

    if (this.contexts.has(accountId)) {
      log.warn(`registry: account already started: ${accountId}, returning existing`);
      return this.contexts.get(accountId)!;
    }

    if (!cfg.enabled) {
      throw new Error(`account disabled: ${accountId}`);
    }
    if (!cfg.tokenKey) {
      throw new Error(`account tokenKey missing: ${accountId} (set ${cfg.tokenKeyEnv ?? "env"})`);
    }

    const promise = this._doStart(accountId, cfg);
    this.inFlight.set(accountId, promise);
    try {
      return await promise;
    } finally {
      this.inFlight.delete(accountId);
    }
  }

  /**
   * 内部: 实际创建 context (P2-1 拆分, 让 inFlight lock 涵盖整个 new+set 临界区)
   */
  private async _doStart(accountId: string, cfg: WppAccountConfig): Promise<AccountContext> {
    const ctx = new AccountContext({ accountId, config: cfg });
    this.contexts.set(accountId, ctx);
    ctx.info(`account started via registry`);
    return ctx;
  }

  get(accountId: string): AccountContext | null {
    return this.contexts.get(accountId) ?? null;
  }

  has(accountId: string): boolean {
    return this.contexts.has(accountId);
  }

  /**
   * 路由解析 (G2-2): 精确匹配 → 大小写不敏感匹配 → null.
   * 故意不做 prefix 模糊匹配 (过于 magic, 易误命中).
   * 故意不做 "default" fallback (调用方应明确知道 accountId; OpenClaw session key 总是带 ID).
   * 空字符串 / null / undefined 一律返回 null (不抛 — 调用方决定如何兜底).
   */
  resolve(query: string | null | undefined): AccountContext | null {
    if (!query) return null;
    const exact = this.contexts.get(query);
    if (exact) return exact;
    const lower = query.toLowerCase();
    for (const [id, ctx] of this.contexts) {
      if (id.toLowerCase() === lower) return ctx;
    }
    return null;
  }

  /**
   * 强制拿 context (找不到抛错). 供 dispatch / send 等"必须有 context"的调用方用,
   * 错误信息含所有已知 accountId 便于排查.
   */
  getOrThrow(accountId: string): AccountContext {
    const ctx = this.contexts.get(accountId);
    if (!ctx) {
      throw new Error(
        `account not found: ${accountId} (known: ${Array.from(this.contexts.keys()).join(", ") || "none"})`,
      );
    }
    return ctx;
  }

  list(): AccountContext[] {
    return Array.from(this.contexts.values());
  }

  size(): number {
    return this.contexts.size;
  }

  /** 所有 account ID (供健康检查 / OpenClaw 路由发现) */
  listIds(): string[] {
    return Array.from(this.contexts.keys());
  }

  // ============ Lifecycle ============

  /**
   * 停止单个账号 (context.stop() + 从 registry 移除).
   * 不存在账号 no-op + warn (不抛 — 避免 shutdown 链路单点失败).
   */
  async stop(accountId: string): Promise<void> {
    const ctx = this.contexts.get(accountId);
    if (!ctx) {
      log.warn(`registry: stop called for unknown account: ${accountId}`);
      return;
    }
    await ctx.stop();
    this.contexts.delete(accountId);
  }

  async stopAll(): Promise<void> {
    const ids = Array.from(this.contexts.keys());
    for (const id of ids) {
      await this.stop(id);
    }
  }

  // ============ DB 持久化 (G2-3) ============
  // 注意: 不自动 persist — caller 决定时机 (start 后 / 鉴权变化后 / stop 前)
  //       自动 persist 易引入循环依赖 + 难测试, 显式调用更可控

  /**
   * 持久化单个账号状态到 DB.
   * 故意不存 tokenKey / authcode / webhookSecret (走 accounts/<id>.json + env vars)
   * 失败 throw — caller 决定 retry / 兜底 (vs AccountContext.stop 失败仅 warn)
   */
  async persist(accountId: string): Promise<void> {
    const ctx = this.get(accountId);
    if (!ctx) {
      log.warn(`registry.persist: account not found: ${accountId}`);
      return;
    }
    const record: AccountRecord = {
      account_id: ctx.accountId,
      display_name: ctx.config.nickname,
      self_wxid: ctx.selfWxid,
      nickname: ctx.config.nickname,
      enabled: ctx.config.enabled,
      config_json: JSON.stringify({
        // 非敏感配置 (供 reload 时参考, 但实际仍以 disk 为准)
        debounceMs: ctx.config.debounceMs,
        requireAtMention: ctx.config.requireAtMention,
        groupPolicy: ctx.config.groupPolicy,
        allowFrom: ctx.config.allowFrom,
        groupAllowFrom: ctx.config.groupAllowFrom,
        apiBaseUrl: ctx.config.apiBaseUrl,
        wsUrl: ctx.config.wsUrl,
        webhookHost: ctx.config.webhookHost,
        webhookPort: ctx.config.webhookPort,
        webhookPath: ctx.config.webhookPath,
        // 故意不存: tokenKey, authcode, webhookSecret (走 disk + env)
      }),
    };
    await upsertAccount(record);
    ctx.debug(`persisted to db (vendorAuthed=${ctx.vendorAuthed})`);
  }

  /**
   * 列出 DB 中所有已知账号 (按 account_id 排序)
   * 供 plugin 重启时遍历 / OpenClaw setup wizard / 监控
   */
  async loadAllFromDb(): Promise<AccountRecord[]> {
    return getAccounts();
  }

  /**
   * 单个账号 DB 状态 (null 表示从未注册过)
   */
  async loadFromDb(accountId: string): Promise<AccountRecord | null> {
    return getAccount(accountId);
  }

  // ============ Debug ============

  /**
   * 调试 dump — 不含敏感字段 (AccountContext.toJSON 已脱敏 tokenKey/authcode/webhookSecret)
   */
  toJSON(): Record<string, unknown> {
    return {
      size: this.contexts.size,
      accountIds: Array.from(this.contexts.keys()),
      accounts: this.list().map((c) => c.toJSON()),
    };
  }
}

// src/accounts/account-context.ts - Phase G1 单账号环境隔离
// 封装 1 个账号的: config + apiClient + 运行时状态 + 隔离 logger
// 仿 本项目 AccountContext 设计 (本仓库 v0.1.0 沿用 module singleton 模式, G1 升级为 class)
//
// 关键不变量:
//      → outbound / dispatch / inbound 现有 call site 不用动

import {
  info as loggerInfo,
  warn as loggerWarn,
  error as loggerError,
  debug as loggerDebug,
  formatErr,
} from "../core/logger.js";
import { WechatpadproApiClient } from "../api-client.js";
import type {
  WppAccountConfig,
  WppApiClient,
  WppWebhookServer,
  WppWsClient,
} from "../types.js";

type Fields = Record<string, unknown>;

export interface AccountContextInit {
  accountId: string;
  config: WppAccountConfig;
}

export class AccountContext {
  readonly accountId: string;
  readonly config: WppAccountConfig;
  readonly apiClient: WppApiClient;
  readonly createdAt: number;

  // 运行时挂载资源 (startAccount 之后由 index.ts attach)
  wsClient?: WppWsClient;
  webhookServer?: WppWebhookServer;

  // v1.1.27 SHUTDOWN-FLUSH (2026-08-08 P1-b): inbound debouncer flushAll 钩子
  //   之前: stop() 拿不到 handler 闭包内 debouncer 引用 → 停机丢失 buffered 消息
  //   fix: index.ts attachInboundFlush(inboundHandler.flushAll), stop() 时先 flush 再停 ws/webhook
  private inboundFlushHook: (() => Promise<void>) | null = null;
  attachInboundFlush(hook: () => Promise<void>): void {
    this.inboundFlushHook = hook;
  }

  // 多个 timer 可能并存 (e.g. 启动失败 + 后续仍 retry), shutdown 时全部 clear
  private readonly retryTimers = new Set<NodeJS.Timeout>();

  // vendor 鉴权状态 (login/checkLogin 成功后由 inbound 流程更新)
  vendorAuthed = false;
  authcode: string;
  selfWxid: string;

  // 私有 logger prefix
  private readonly logPrefix: string;

  constructor(init: AccountContextInit) {
    this.accountId = init.accountId;
    this.config = init.config;
    // v1.3.56 MULTI-ACCOUNT: client 持真实 accountId (OSS key/入库/日志按账号分桶)
    this.apiClient = new WechatpadproApiClient(init.config, init.accountId);
    this.createdAt = Date.now();
    this.authcode = init.config.authcode;
    this.selfWxid = init.config.selfWxid;
    this.logPrefix = `[WPP:${this.accountId}]`;
  }

  // ============ 隔离 logger (4 件套) ============
  // 每条 log 自动带 accountId 字段 + [WPP:<id>] 前缀
  // → 多账号并发时 grep `accountId=` 即可过滤单账号流量

  info(msg: string, fields?: Fields): void {
    loggerInfo(`${this.logPrefix} ${msg}`, { accountId: this.accountId, ...(fields ?? {}) });
  }

  warn(msg: string, fields?: Fields): void {
    loggerWarn(`${this.logPrefix} ${msg}`, { accountId: this.accountId, ...(fields ?? {}) });
  }

  error(msg: string, err?: unknown): void {
    loggerError(`${this.logPrefix} ${msg}`, {
      accountId: this.accountId,
      err: err === undefined ? undefined : formatErr(err),
    });
  }

  debug(msg: string, fields?: Fields): void {
    loggerDebug(`${this.logPrefix} ${msg}`, { accountId: this.accountId, ...(fields ?? {}) });
  }

  // ============ 状态变更 (setter 都走 logger 留痕) ============

  /**
   * v1.1.15 HOT-RELOAD (2026-08-08 接总立方案 A): 运行时更新配置
   * readonly 只禁止换引用, 不禁止改字段 → Object.assign 原地更新
   * 所有持 this.config 引用的运行时读点 (allowFrom/groupPolicy/requireAtMention 等) 即刻生效
   * 注: apiClient 是构造时 new 的 (持旧 config 引用), 改 baseUrl/tokenKey 需重建 client 的场景
   *    (极少数) 暂不支持, 热重载主要覆盖运行时决策字段 (白名单/群策略/@要求/debounce)
   */
  updateConfig(patch: Partial<WppAccountConfig>): void {
    const changed: string[] = [];
    const target = this.config as unknown as Record<string, unknown>;
    for (const [k, v] of Object.entries(patch)) {
      if (k === "authcode" || k === "selfWxid") continue; // 下面单独处理
      if (JSON.stringify(target[k]) !== JSON.stringify(v)) {
        changed.push(k);
      }
      target[k] = v;
    }
    // 同步鉴权字段 (构造时从 config 拷的独立字段)
    if (patch.authcode !== undefined && patch.authcode !== this.authcode) {
      this.authcode = patch.authcode;
      changed.push("authcode");
    }
    if (patch.selfWxid !== undefined && patch.selfWxid !== this.selfWxid) {
      this.selfWxid = patch.selfWxid;
      changed.push("selfWxid");
    }
    if (changed.length > 0) {
      this.info(`config hot-reloaded`, { changed: changed.join(",") });
    } else {
      this.debug(`config hot-reload no-op (无变化)`);
    }
  }

  setVendorAuth(selfWxid: string, authcode: string): void {
    this.vendorAuthed = true;
    this.selfWxid = selfWxid;
    this.authcode = authcode;
    this.info(`vendor auth updated`, { selfWxid });
  }

  attachWsClient(ws: WppWsClient): void {
    this.wsClient = ws;
    this.info(`ws client attached`);
  }

  attachWebhookServer(srv: WppWebhookServer): void {
    this.webhookServer = srv;
    this.info(`webhook server attached`, { port: this.config.webhookPort, path: this.config.webhookPath });
  }

  // 启动时 setWebhook 失败 → 后台每 5 分钟重试, 成功 clearInterval
  // shutdown 时统一 clear (防泄漏)
  setRetryTimer(timer: NodeJS.Timeout): void {
    this.retryTimers.add(timer);
  }
  clearRetryTimer(timer?: NodeJS.Timeout): void {
    if (timer) {
      this.retryTimers.delete(timer);
      clearInterval(timer);
    } else {
      // 清空所有 (shutdown 时调)
      for (const t of this.retryTimers) clearInterval(t);
      this.retryTimers.clear();
    }
  }

  // ============ 派生属性 ============

  get isConfigured(): boolean {
    return !!(this.config.enabled && this.config.tokenKey && this.config.apiBaseUrl);
  }

  get isEnabled(): boolean {
    return this.config.enabled === true;
  }

  get vendorBaseUrl(): string {
    return this.config.apiBaseUrl.replace(/\/$/, "");
  }

  // ============ 生命周期 ============

  /**
   * 优雅停止: 停 ws + webhook, 不抛 (单个失败不影响另一个)
   * registry.delete 由 AccountRegistry 在调用 stop 后负责 (G2)
   */
  async stop(): Promise<void> {
    if (this.retryTimers.size > 0) {
      this.clearRetryTimer();
      this.info(`cleared ${this.retryTimers.size} retry timer(s)`);
    }
    // v1.1.27 SHUTDOWN-FLUSH: 先 flush debouncer (buffered 消息), 再停 ws/webhook
    //   顺序很重要: flush 完成后 ws/webhook 才能安全停, 否则消息进 debouncer 但 handler 已关
    if (this.inboundFlushHook) {
      try {
        await this.inboundFlushHook();
        this.info(`inbound flush completed (debouncer buffered messages dispatched)`);
      } catch (e) {
        this.warn(`inbound flush error: ${formatErr(e)}`);
      }
    }
    if (this.wsClient) {
      try {
        await this.wsClient.stop();
      } catch (e) {
        this.warn(`ws stop error: ${formatErr(e)}`);
      }
    }
    if (this.webhookServer) {
      try {
        await this.webhookServer.stop();
      } catch (e) {
        this.warn(`webhook stop error: ${formatErr(e)}`);
      }
    }
    this.info(`account context stopped`);
  }

  /**
   * 调试 dump: 不包含 tokenKey / authcode / webhookSecret (敏感字段)
   */
  toJSON(): Record<string, unknown> {
    return {
      accountId: this.accountId,
      createdAt: this.createdAt,
      enabled: this.config.enabled,
      vendorBaseUrl: this.vendorBaseUrl,
      vendorAuthed: this.vendorAuthed,
      selfWxid: this.selfWxid,
      hasWsClient: !!this.wsClient,
      hasWebhookServer: !!this.webhookServer,
      wsConnected: this.wsClient?.isConnected() ?? false,
    };
  }
}

// src/api-client.ts - WeChatPadPro HTTP API compat shim
// v1.3.19 UNIFY-SEND: 降级为**薄 adapter** — 所有发送方法委托到 send/<tag>.ts (makeWppMsg),
//   行为单点维护在 send/ 层 (查找/扩展/修复只改一处)。保留 WppApiClient interface, 调用方零改动。
//
// 关键:
//   - sendText/sendImage/sendVoice/sendVideo/revokeMsg/syncMessage → makeWppMsg (persist:false)
//     入库由 outbound.ts 的 persistOutbound 负责 (避免双份入库)
//   - sendFileViaApp 保留实现 (send/msg.ts 的 sendFile 内部调它, 不循环委托)
//   - call<T> 通用端点调用保留 (ws-client/index 用)
//   - resolveImageToBase64/readLocalMedia 移到 src/api/resolve-media.ts, 此处 re-export 兼容旧测试

import { postWppJson, getWppJson, stringifyLargeInts } from "./api/client.js";
import { logObj as log } from "./core/logger.js";
import { safeFetchWithCap } from "./util/safe-fetch.js";
import { makeWppMsg } from "./send/msg.js";
import { makeWppGroup } from "./send/group.js";
import { makeWppFriend } from "./send/friend.js";
import { makeWppWebhook } from "./send/webhook.js";
import type { WppAccountConfig, WppApiClient, WppApiResponse } from "./types.js";

export { resolveImageToBase64, readLocalMedia } from "./api/resolve-media.js";

/** XML 转义 (v1.3.12 FILE-SEND: 文件名含特殊字符时防 XML 破坏) */
function escapeXml(s: string): string {
  return String(s ?? "").replace(/[<>&'"]/g, (c) => {
    switch (c) {
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "&": return "&amp;";
      case "'": return "&apos;";
      case '"': return "&quot;";
      default: return c;
    }
  });
}

/** 构造 makeWppXxx ctx (由 cfg 派生, 行为对齐 send/ 层; v1.3.56 MULTI-ACCOUNT: accountId 透传真实 id) */
function makeCtx(cfg: WppAccountConfig, accountId: string) {
  return {
    baseUrl: cfg.apiBaseUrl,
    tokenKey: cfg.tokenKey,
    authcode: cfg.authcode,
    accountId,
  };
}

function makeMsgFor(cfg: WppAccountConfig, accountId: string) {
  return makeWppMsg(makeCtx(cfg, accountId));
}
function makeGroupFor(cfg: WppAccountConfig, accountId: string) {
  return makeWppGroup(makeCtx(cfg, accountId));
}
function makeFriendFor(cfg: WppAccountConfig, accountId: string) {
  return makeWppFriend(makeCtx(cfg, accountId));
}
function makeWebhookFor(cfg: WppAccountConfig, accountId: string) {
  return makeWppWebhook(makeCtx(cfg, accountId));
}

export class WechatpadproApiClient implements WppApiClient {
  private accountId: string;
  constructor(private cfg: WppAccountConfig, accountId?: string) {
    // v1.3.56 MULTI-ACCOUNT: 每账号独立 client 持自己的 accountId (OSS key/日志/入库用)
    this.accountId = accountId ?? "default";
  }

  getBaseUrl(): string {
    return this.cfg.apiBaseUrl.replace(/\/$/, "");
  }

  getTokenKey(): string {
    return this.cfg.tokenKey;
  }

  /** 通用 POST 调用 (authcode/query 由 postWppJson 自动注入) */
  async call<T = unknown>(endpoint: string, body: Record<string, unknown> = {}): Promise<WppApiResponse<T>> {
    return postWppJson<T>(this.cfg.apiBaseUrl, endpoint, body, {
      tokenKey: this.cfg.tokenKey,
      authcode: this.cfg.authcode,
    });
  }

  /** 通用 GET 调用 (authcode/query 由 getWppJson 自动注入) */
  private async get<T = unknown>(endpoint: string): Promise<WppApiResponse<T>> {
    return getWppJson<T>(this.cfg.apiBaseUrl, endpoint, {
      tokenKey: this.cfg.tokenKey,
      authcode: this.cfg.authcode,
    });
  }

  // ============ Login (委托 send/msg.ts? 不 — login 走 send/login.ts, 但这里保留原实现兼容) ============
  async login(): Promise<{ qrcodeUrl: string; qrcodeData?: string }> {
    const r = await this.call<{ qrcodeUrl?: string; qrcodeData?: string }>("/Login/GetQR", {
      authcode: this.cfg.authcode,
    });
    const d = r.Data ?? {};
    return { qrcodeUrl: d.qrcodeUrl ?? "", qrcodeData: d.qrcodeData };
  }

  async checkLogin(uuid: string): Promise<{ status: number; expired?: boolean; acctSectResp?: unknown }> {
    const r = await this.call("/Login/CheckQR", { uuid, authcode: this.cfg.authcode });
    const d = (r.Data ?? {}) as { status?: number; expired?: boolean; acctSectResp?: unknown };
    return { status: d.status ?? 0, expired: d.expired, acctSectResp: d.acctSectResp };
  }

  async logout(): Promise<WppApiResponse> {
    return this.call("/Login/LogOut", {});
  }

  async heartbeat(): Promise<WppApiResponse> {
    return this.call("/Login/HeartBeat", {});
  }

  // ============ Msg (v1.3.19 UNIFY-SEND: 委托 send/msg.ts, persist:false 防双入库) ============
  async sendText(toWxid: string, text: string, ats?: string[]): Promise<WppApiResponse> {
    const api = makeMsgFor(this.cfg, this.accountId);
    return api.sendTxt(toWxid, text, ats, false);
  }

  async sendImage(toWxid: string, imageUrlOrPath: string): Promise<WppApiResponse> {
    const api = makeMsgFor(this.cfg, this.accountId);
    return api.sendImage(toWxid, imageUrlOrPath, false);
  }

  async sendVoice(toWxid: string, voiceUrlOrPath: string, durationMs?: number, formatHint?: "mp3" | "silk"): Promise<WppApiResponse> {
    const api = makeMsgFor(this.cfg, this.accountId);
    return api.sendVoice(toWxid, voiceUrlOrPath, durationMs, false, formatHint);
  }

  async sendVideo(
    toWxid: string,
    videoUrlOrPath: string,
    thumbUrlOrPath?: string,
    playLengthMs?: number,
  ): Promise<WppApiResponse> {
    const api = makeMsgFor(this.cfg, this.accountId);
    return api.sendVideo(toWxid, videoUrlOrPath, thumbUrlOrPath, playLengthMs, false);
  }

  // /Msg/SendApp 是「群发消息」(SendGroupMassMsgTextParamDoc)
  //   不是发 XML 应用消息，正确端点是 /Msg/ShareLink (SendAppMsgParamDoc: { ToWxid, Type, Xml })
  async sendApp(toWxid: string, xml: string): Promise<WppApiResponse> {
    return this.call("/Msg/ShareLink", { ToWxid: toWxid, Type: 5, Xml: xml });
  }

  /**
   * v1.3.12 FILE-SEND: 发送文件 (UploadFile 上传 → ShareLink type=6 文件 XML)。
   * 实测 SendCDNFile Content 各种格式 (mediaId/file_no/aeskey/XML) 全 Ret=-2 (vendor 未实现);
   * SendApp type=6 appmsg 可发可打开 (但微信端显示"未审核应用"标签, 接受 — 方案 C 老板拍板)。
   *
   * v1.3.18 P1-安全2: fileUrl (cdnUrl) 走 safeFetchWithCap, 防 SSRF + 字节 cap (50MB, 文件通常 <20MB)
   * (sendFile 转 base64 上传 vendor — 这方法本身接 base64, 不 fetch, 不需要改)
   *
   * 保留实现 (send/msg.ts 的 sendFile 内部调它, 不循环委托)。
   */
  async sendFileViaApp(
    toWxid: string,
    fileName: string,
    fileBase64: string,
    fileSize: number,
    fileUrl?: string,
  ): Promise<WppApiResponse> {
    let payloadBase64 = fileBase64;
    if (fileUrl && (!fileBase64 || fileBase64.length === 0)) {
      try {
        const buf = await safeFetchWithCap(fileUrl, { signal: AbortSignal.timeout(60_000) }, 50 * 1024 * 1024);
        payloadBase64 = buf.toString("base64");
      } catch (e) {
        const errMsg = (e as Error).message ?? String(e);
        return { Code: -2, CodeValue: `FETCH_FAIL:${errMsg.slice(0, 80)}`, Data: null, raw: null };
      }
    }
    const up = await this.call("/Tools/UploadFile", { base64: payloadBase64 });
    const mediaId = ((up.Data ?? {}) as { mediaId?: string }).mediaId ?? "";
    if (!mediaId) {
      return { ...up, Code: -2, CodeValue: "UPLOAD_NO_MEDIA_ID" };
    }
    const ext = (fileName.split(".").pop() || "dat").toLowerCase();
    const xml =
      `<appmsg appid="wxfile" sdkver="0">` +
      `<title>${escapeXml(fileName)}</title>` +
      `<des></des><action>view</action><type>6</type>` +
      `<content>dataType=1|filename=${escapeXml(fileName)}|fileext=${ext}|totallen=${fileSize}|attachid=${mediaId}|</content>` +
      `<appattach><totallen>${fileSize}</totallen><attachid>${mediaId}</attachid><fileext>${ext}</fileext></appattach>` +
      `</appmsg>`;
    return this.call("/Msg/ShareLink", { ToWxid: toWxid, Type: 6, Xml: xml });
  }

  async revokeMsg(msgId: string, newMsgId: string, toWxid: string, createTime?: number): Promise<WppApiResponse> {
    const api = makeMsgFor(this.cfg, this.accountId);
    return api.revoke(msgId, newMsgId, toWxid, createTime);
  }

  // vendor swagger /Msg/Sync body schema = Msg.SyncParamDoc
  async syncMessage(): Promise<WppApiResponse> {
    const api = makeMsgFor(this.cfg, this.accountId);
    return api.sync();
  }

  // ============ Group (委托 send/group.ts) ============
  async getChatroomInfo(chatroomId: string): Promise<WppApiResponse> {
    return makeGroupFor(this.cfg, this.accountId).getInfo(chatroomId);
  }

  // /Group/GetChatRoomMemberList 404 → /Group/GetChatRoomMemberDetail 200
  async getChatroomMemberList(chatroomId: string): Promise<WppApiResponse> {
    return makeGroupFor(this.cfg, this.accountId).getMemberDetail(chatroomId);
  }

  // ============ Friend (委托 send/friend.ts) ============
  async getContactList(): Promise<WppApiResponse> {
    return makeFriendFor(this.cfg, this.accountId).getContractList();
  }

  // ============ User (保留原实现: GET /User/GetContractProfile) ============
  // /User/GetProfile 404 → /User/GetContractProfile 200; swagger authcode 在 query
  async getProfile(): Promise<WppApiResponse> {
    return this.get("/User/GetContractProfile");
  }

  // ============ Webhook (委托 send/webhook.ts) ============
  async setWebhook(url: string, _authcode: string): Promise<WppApiResponse> {
    // webhook.set 保留 v1.1.17 P0-E enabled:true 修复; authcode 由 ctx 注入 (与调用方传的 cfg.authcode 同值)
    return makeWebhookFor(this.cfg, this.accountId).set(url);
  }

  async getWebhook(): Promise<WppApiResponse> {
    return makeWebhookFor(this.cfg, this.accountId).get();
  }

  // setBusinessWebhook 字段不同 (syncMessageUrl/logoutUrl), 保留原实现
  async setBusinessWebhook(syncMessageUrl: string, logoutUrl: string): Promise<WppApiResponse> {
    return this.call("/Webhook/Business/Set", { syncMessageUrl, logoutUrl });
  }

  async startAutoSync(targetUrl: string): Promise<WppApiResponse> {
    return makeMsgFor(this.cfg, this.accountId).startAutoSync(targetUrl);
  }

  async removeWebhook(): Promise<WppApiResponse> {
    return makeWebhookFor(this.cfg, this.accountId).remove();
  }
}

