// src/util/bigint.ts - 大整数精度保护 (纯字符串工具, 低层, 无依赖)
//
// v1.3.27 (2026-08-10, P2-1): stringifyLargeInts 从 api/client.ts 移入本文件.
//   原因: config.ts / inbound/handler.ts 也要用, 但 config.ts 是低层配置模块,
//   import api/client.ts 会拖入 account-state → db → registry 整条链 (启动副作用 + 架构方向反).
//   移入 util/ 后低层模块直接 import, api/client.ts 保留 re-export 兼容老调用方/测试.

/**
 * Pre-process JSON text to wrap 16+ digit integers as quoted strings.
 * 关键: vendor 返回的 msg_id / new_msg_id 可能 16+ 位 (e.g. 1899234567890123456),
 *       不预先引号化 → JSON.parse 会丢精度 (Number.MAX_SAFE_INTEGER = 9007199254740992)
 *       silent killer: 消息回查时找不到
 */
export function stringifyLargeInts(jsonText: string): string {
  // 匹配 key 后接 16+ 整数 value 的 :1234567890123456,
  // 后面可以是 ,/空格/}/] 或字符串末尾
  return jsonText.replace(
    /("[\w$]+"\s*:\s*)(\d{16,})(?=[,\s}\]]|$)/g,
    '$1"$2"',
  );
}

// src/send/quote-xml.ts - 引用回复 XML 构造
// 关键: appmsg type=57 客户端主气泡读 <title> 字段, <des> 在 type=57 被吞。
// 因此 title = AI 回复文字 (gewe 工作基线), 不能放被引用人 displayname (否则只显示 refermsg 预览)。

export interface QuoteSource {
  /** 被引用消息的 svrid (= inbound NewMsgId, vendor 全局唯一) */
  svrid: string;
  /** 被引用消息的发送者 wxid */
  fromusr?: string;
  /** 被引用消息的所属会话 wxid (群聊时 = 群id, 私聊时 = 对方 wxid) */
  chatusr?: string;
  /** 被引用消息的发送者昵称 (用于引用块展示) */
  displayname?: string;
  /** 被引用消息的原文 (文本=原文, 图片=图片 XML) */
  content?: string;
  /** 被引用消息的创建时间 (秒) */
  createtime?: number;
  /** 被引用消息的类型 (1=text 3=image 34=voice 43=video 47=emoji 49=app) */
  innerType?: number;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/**
 * 引用回复 XML: title=des=AI 回复 (双填保险, 老客户端可能读 des), type=57, refermsg=svrid+fromusr
 */
export function buildQuoteReplyXml(
  replyContent: string,
  quote: QuoteSource,
  opts?: { innerType?: 57 | 49 },
): string {
  const innerType = opts?.innerType ?? 57;
  const reply = (replyContent || "引用回复").trim();
  const title = escapeXml(reply.slice(0, 500));
  const des = escapeXml(reply.slice(0, 500));

  // refermsg 极简化 (gewe 基线): 仅 svrid 客户端已能渲染; 加 fromusr 兼容老版本回查昵称
  const svrid = escapeXml(quote.svrid.trim());
  const fromusr = quote.fromusr ? escapeXml(quote.fromusr) : "";

  const refermsg = svrid
    ? `<refermsg>` +
      `<svrid>${svrid}</svrid>` +
      (fromusr ? `<fromusr>${fromusr}</fromusr>` : "") +
      `</refermsg>`
    : "";

  return `<appmsg><title>${title}</title><des>${des}</des><type>${innerType}</type>${refermsg}</appmsg>`;
}

// src/inbound/quote-svrid.ts - 引用消息 svrid 捕获 (v1.1.24)
// 2026-08-08 19:39 接总立验证成功: 真实 svrid (从引用消息 refermsg) + 完整图片 XML → 能定位 + 缩略图
// 核心: 微信 svrid 无法主动获取 (vendor 不提供), 只能从"别人引用该消息"的 refermsg.svrid 被动捕获
// 捕获后存 DB 映射 (md5 → svrid), AI 引用时优先查真实 svrid

import { parseQuoteXml } from "./parser/quote.js";
import { info, warn } from "../core/logger.js";
import { saveSvridMapping, getSvridByMd5 } from "../db.js";

/**
 * 从引用消息 content 里提取被引用图片的 md5
 * refermsg.content 是被引用消息原文 — 图片时含 <img ... md5="...">
 */
export function extractQuotedImgMd5(content: string | undefined): string | undefined {
  if (!content) return undefined;
  const m = content.match(/md5="([0-9a-f]{32})"/i);
  return m ? m[1] : undefined;
}

/**
 * 捕获引用消息的 svrid → 存 DB 映射
 * 被引用消息 (refermsg.content) 的 md5 → svrid 关联
 * @param msgContent 收到的引用消息完整 content (含 refermsg)
 * @param accountId 账号
 */
export async function captureQuoteSvrid(
  msgContent: string,
  accountId: string,
): Promise<{ svrid?: string; md5?: string; captured: boolean }> {
  if (!msgContent.includes("<refermsg")) {
    return { captured: false };
  }
  const parsed = parseQuoteXml(msgContent);
  if (!parsed?.msgId) {
    return { captured: false };
  }
  const svrid = parsed.msgId;
  // 被引用内容: 图片 → md5; 文本 → 无 md5
  const quotedContent = parsed.content;
  const md5 = extractQuotedImgMd5(quotedContent);

  try {
    // 存映射 (md5 → svrid); 文本消息 md5 为 null, 用 content hash 兜底
    await saveSvridMapping({
      account_id: accountId,
      svrid,
      msg_md5: md5 ?? null,
      // 被引用消息的 new_msg_id 可作关联线索 (如有)
      quoted_content_hash: quotedContent ? simpleHash(quotedContent.slice(0, 200)) : null,
      captured_at: Math.floor(Date.now() / 1000),
    });
    info(
      `[WPP v1.2.0] quote svrid captured: svrid=${svrid} md5=${md5 ?? "(text)"} (account=${accountId})`,
    );
    return { svrid, md5: md5 ?? undefined, captured: true };
  } catch (e) {
    warn(`[WPP v1.2.0] quote svrid capture failed (non-fatal): ${e instanceof Error ? e.message : String(e)}`);
    return { svrid, md5: md5 ?? undefined, captured: false };
  }
}

function simpleHash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (h << 5) - h + s.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

/**
 * 查真实 svrid: 优先 md5 映射, fallback 被引用消息的 new_msg_id
 * @param msgId 被引用消息 msg_id (DB 查询)
 * @param newMsgId 被引用消息 new_msg_id
 * @param content 被引用消息 content (含 md5 的话)
 * @param accountId 账号
 */
export async function resolveQuoteSvrid(
  msgId: string,
  newMsgId: string | undefined,
  content: string | undefined,
  accountId: string,
): Promise<string> {
  const md5 = extractQuotedImgMd5(content);
  if (md5) {
    const svrid = await getSvridByMd5(md5, accountId);
    if (svrid) {
      info(`[WPP v1.2.0] svrid resolved via md5: ${svrid} (md5=${md5})`);
      return svrid;
    }
  }
  if (newMsgId) {
    return newMsgId;
  }
  return msgId;
}

// src/inbound/parser/quote.ts - 引用消息 <refermsg> XML 解析

import { safeMatch } from "../../core/safe-regex.js";

export interface QuoteRef {
  msgId: string;
  newMsgId?: string;
  fromWxid?: string;
  title?: string;
  type?: string;
  /** 被引用消息原文 (文本=原文, 图片=图片XML) */
  content?: string;
}

/** Parse `<refermsg type="..."><type>...</type><svrid>...</svrid>...</refermsg>` block */
export function parseQuoteXml(content: string): QuoteRef | null {
  if (!content || !content.includes("<refermsg")) return null;
  // 用 safeMatch 截断 4096 防恶意构造 XML 触发 ReDoS
  const block = safeMatch(/<refermsg\b[^>]*>([\s\S]*?)<\/refermsg>/, content);
  if (!block || block[1] === undefined) return null;
  const inner = block[1];

  const tag = (name: string): string | undefined => {
    const m = safeMatch(new RegExp(`<${name}>([\\s\\S]*?)<\\/${name}>`), inner, 2048);
    return m && m[1] ? m[1].trim() : undefined;
  };

  const result: QuoteRef = {
    type: tag("type"),
    msgId: tag("svrid") ?? tag("msgid") ?? "",
    // 真实结构是 <fromusr> (不是 fromusername)
    fromWxid: tag("fromusr") ?? tag("fromusername"),
    title: tag("displayname") ?? tag("title"),
    content: tag("content"),
  };
  if (!result.msgId) return null;
  return result;
}

/**
 * v1.3.5 QUOTE-REPLY-CONTEXT: 新版 vendor 引用走 raw_payload.reply_context (非 content <refermsg> XML)。
 * 结构: { msg_id: uint32, new_msg_id, svr_id, quote_content, msg_type, from_user_id, ... }
 * 提取被引用消息的定位字段 (msg_id 可能是被引用消息 local_id, svr_id 可能是当前消息自身)。
 */
export interface ReplyContextRef {
  /** vendor 内部 msg_id (uint32) — 可能是被引用消息 local_id */
  msgId?: number;
  newMsgId?: string;
  svrId?: string;
  /** 被引用内容文字 (图片消息则为描述) */
  quoteContent?: string;
  /** 被引用消息类型 (3=图片, 49=文件, 1=文本...) */
  msgType?: number;
  fromWxid?: string;
  chatroomId?: string;
}

/** 从 raw_payload 提取 reply_context 引用信息 (无则 null) */
export function extractReferencedFromReplyContext(raw: unknown): ReplyContextRef | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const rc = r.reply_context as Record<string, unknown> | undefined;
  if (!rc || typeof rc !== "object") return null;
  return {
    msgId: typeof rc.msg_id === "number" ? rc.msg_id : undefined,
    newMsgId: typeof rc.new_msg_id === "string" ? rc.new_msg_id : undefined,
    svrId: typeof rc.svr_id === "string" ? rc.svr_id : undefined,
    quoteContent: typeof rc.quote_content === "string" ? rc.quote_content : undefined,
    msgType: typeof rc.msg_type === "number" ? rc.msg_type : undefined,
    fromWxid: typeof rc.from_user_id === "string" ? rc.from_user_id : undefined,
    chatroomId: typeof rc.chat_user_id === "string" ? rc.chat_user_id : undefined,
  };
}

/**
 * v1.3.6 QUOTE-APP-REFERENCE: 新版 vendor 引用消息的**被引用信息在 app.reference** (category=quote),
 * 不在 reply_context! 结构:
 *   app: { category: "quote", reference: { new_msg_id, svr_id, msg_type, from_user_id, display_name } }
 * 实测: app.reference.new_msg_id 精确匹配 DB msg_id 列 → 定位被引用消息 (图/文件/文本)
 */
export interface AppReference {
  newMsgId?: string;
  svrId?: string;
  msgType?: number;
  fromWxid?: string;
  displayName?: string;
}

/** 从 raw_payload 提取 app.reference (category=quote 引用消息) 被引用信息 */
export function extractReferencedFromApp(raw: unknown): AppReference | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const app = r.app as Record<string, unknown> | undefined;
  if (!app || typeof app !== "object") return null;
  if (app.category !== "quote") return null;
  const ref = app.reference as Record<string, unknown> | undefined;
  if (!ref || typeof ref !== "object") return null;
  return {
    newMsgId: typeof ref.new_msg_id === "string" ? ref.new_msg_id : undefined,
    svrId: typeof ref.svr_id === "string" ? ref.svr_id : undefined,
    msgType: typeof ref.msg_type === "number" ? ref.msg_type : undefined,
    fromWxid: typeof ref.from_user_id === "string" ? ref.from_user_id : undefined,
    displayName: typeof ref.display_name === "string" ? ref.display_name : undefined,
  };
}
